CREATE TABLE principals(subject TEXT PRIMARY KEY) STRICT;
CREATE TABLE tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_subject TEXT NOT NULL REFERENCES principals(subject)) STRICT;
CREATE TABLE memberships(tenant_id TEXT NOT NULL REFERENCES tenants(id), subject TEXT NOT NULL REFERENCES principals(subject), role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(tenant_id,subject)) STRICT;
CREATE TABLE sites(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), UNIQUE(tenant_id,id)) STRICT;
CREATE TABLE drafts(site_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), document TEXT NOT NULL CHECK(json_valid(document)), hash TEXT NOT NULL, FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE draft_history(site_id TEXT NOT NULL, tenant_id TEXT NOT NULL, version INTEGER NOT NULL, document TEXT NOT NULL CHECK(json_valid(document)), hash TEXT NOT NULL, actor TEXT NOT NULL REFERENCES principals(subject), PRIMARY KEY(site_id,version), FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE uploads(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, actor TEXT NOT NULL REFERENCES principals(subject), object_key TEXT NOT NULL UNIQUE, hash TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=31457280), mime TEXT NOT NULL CHECK(mime IN ('image/jpeg','image/png')), filename TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('staged','committed','aborted')), FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE assets(id TEXT PRIMARY KEY REFERENCES uploads(id), tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, hash TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), mime TEXT NOT NULL, width INTEGER NOT NULL CHECK(width>0), height INTEGER NOT NULL CHECK(height>0 AND width*height<=32000000), UNIQUE(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE domains(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, hostname TEXT NOT NULL UNIQUE, challenge TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','verified','revoked')), evidence TEXT, expires_at INTEGER, UNIQUE(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE releases(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, source_version INTEGER NOT NULL, document TEXT NOT NULL CHECK(json_valid(document)), hash TEXT NOT NULL, manifest TEXT NOT NULL CHECK(json_valid(manifest)), actor TEXT NOT NULL REFERENCES principals(subject), UNIQUE(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TABLE release_assets(release_id TEXT NOT NULL, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, asset_id TEXT NOT NULL, PRIMARY KEY(release_id,asset_id), FOREIGN KEY(tenant_id,site_id,release_id) REFERENCES releases(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id,asset_id) REFERENCES assets(tenant_id,site_id,id)) STRICT;
CREATE TABLE publication_jobs(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, release_id TEXT NOT NULL, domain_id TEXT NOT NULL, actor TEXT NOT NULL REFERENCES principals(subject), idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, expected_generation INTEGER NOT NULL CHECK(expected_generation>=0), state TEXT NOT NULL CHECK(state IN ('pending','committed','failed')), artifact TEXT CHECK(artifact IS NULL OR json_valid(artifact)), failure TEXT, UNIQUE(tenant_id,site_id,idempotency_key), UNIQUE(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id,release_id) REFERENCES releases(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id,domain_id) REFERENCES domains(tenant_id,site_id,id)) STRICT;
CREATE TABLE publication_heads(site_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>=0), release_id TEXT, job_id TEXT, domain_id TEXT, FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id), FOREIGN KEY(tenant_id,site_id,release_id) REFERENCES releases(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id,job_id) REFERENCES publication_jobs(tenant_id,site_id,id), FOREIGN KEY(tenant_id,site_id,domain_id) REFERENCES domains(tenant_id,site_id,id)) STRICT;
CREATE TABLE publication_events(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, site_id TEXT NOT NULL, actor TEXT NOT NULL REFERENCES principals(subject), action TEXT NOT NULL CHECK(action IN ('activate','rollback')), from_job TEXT, to_job TEXT NOT NULL, generation INTEGER NOT NULL, created_at INTEGER NOT NULL, FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id)) STRICT;
CREATE TRIGGER immutable_releases_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT,'Immutable release'); END;
CREATE TRIGGER immutable_releases_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT,'Immutable release'); END;
CREATE TRIGGER immutable_assets_update BEFORE UPDATE ON assets BEGIN SELECT RAISE(ABORT,'Immutable original'); END;
CREATE TRIGGER immutable_assets_delete BEFORE DELETE ON assets BEGIN SELECT RAISE(ABORT,'Immutable original'); END;
CREATE TRIGGER immutable_history_update BEFORE UPDATE ON draft_history BEGIN SELECT RAISE(ABORT,'Immutable draft history'); END;
CREATE TRIGGER immutable_history_delete BEFORE DELETE ON draft_history BEGIN SELECT RAISE(ABORT,'Immutable draft history'); END;
CREATE TRIGGER immutable_manifest_update BEFORE UPDATE ON release_assets BEGIN SELECT RAISE(ABORT,'Immutable manifest'); END;
CREATE TRIGGER immutable_manifest_delete BEFORE DELETE ON release_assets BEGIN SELECT RAISE(ABORT,'Immutable manifest'); END;
